#!/usr/bin/env python3
"""Records native process-per-sample timing, as bench/wasm_tier.py measures it, repeated over
time and over cores. Reads only: runs the given ELF files; writes one JSON receipt."""
import json, os, subprocess, sys, time, statistics, hashlib

def freq(cpu):
    try: return int(open(f'/sys/devices/system/cpu/cpu{cpu}/cpufreq/scaling_cur_freq').read())
    except Exception: return None

def one_round(command, cpu, samples=11, warm_ms=150):
    pre = ['taskset', '-c', str(cpu)] if cpu is not None else []
    env = {'PATH': '/usr/bin:/bin', 'LANG': 'C'}
    warm = 0; t0 = time.perf_counter_ns()
    while (time.perf_counter_ns() - t0) / 1e6 < warm_ms:
        r = subprocess.run(pre + command, env=env, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
        if r.returncode != 42: raise SystemExit(f'exit {r.returncode}')
        warm += 1
    f0 = freq(cpu if cpu is not None else 0)
    out = []
    for _ in range(samples):
        s = time.perf_counter_ns()
        r = subprocess.run(pre + command, env=env, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
        out.append((time.perf_counter_ns() - s) / 1e6)
        if r.returncode != 42: raise SystemExit(f'exit {r.returncode}')
    return {'cpu': cpu, 'warmup_count': warm, 'freq_khz_before': f0, 'freq_khz_after': freq(cpu if cpu is not None else 0),
            'batch_ms': out, 'median_per_call_us': statistics.median(out) / 32 * 1000}

def fences(xs):
    s = sorted(xs); n = len(s)
    def q(p):
        i = (n - 1) * p; lo = int(i); hi = min(lo + 1, n - 1)
        return s[lo] + (s[hi] - s[lo]) * (i - lo)
    q1, q3 = q(0.25), q(0.75); iqr = q3 - q1
    return q1 - 1.5 * iqr, q3 + 1.5 * iqr

if __name__ == '__main__':
    elfs = dict(a.split('=', 1) for a in sys.argv[2:])
    rounds = int(os.environ.get('ROUNDS', '24'))
    cpus = [None] + [int(c) for c in os.environ.get('CPUS', '0,2,4').split(',') if c != '']
    receipt = {'measured_at': time.strftime('%Y-%m-%dT%H:%M:%S%z'), 'loadavg_before': open('/proc/loadavg').read().split()[:3],
               'governor': open('/sys/devices/system/cpu/cpu0/cpufreq/scaling_governor').read().strip(),
               'elfs': {k: {'path': v, 'sha256': hashlib.sha256(open(v, 'rb').read()).hexdigest(), 'bytes': os.path.getsize(v)} for k, v in elfs.items()},
               'rounds': []}
    for r in range(rounds):
        order = list(elfs) if r % 2 == 0 else list(reversed(list(elfs)))
        for cpu in cpus:
            for name in order:
                res = one_round([elfs[name]], cpu); res.update(name=name, round=r)
                receipt['rounds'].append(res)
    receipt['loadavg_after'] = open('/proc/loadavg').read().split()[:3]
    for name in elfs:
        for cpu in cpus:
            xs = [x for rr in receipt['rounds'] if rr['name'] == name and rr['cpu'] == cpu for x in rr['batch_ms']]
            lo, hi = fences(xs); inc = [x for x in xs if lo <= x <= hi]
            meds = [rr['median_per_call_us'] for rr in receipt['rounds'] if rr['name'] == name and rr['cpu'] == cpu]
            print(f"{name:8} cpu={cpu!s:5} samples={len(xs):4d} excl={len(xs)-len(inc):3d} median_us/call={statistics.median(inc)/32*1000:8.2f} "
                  f"min={min(xs)/32*1000:8.2f} max={max(xs)/32*1000:8.2f} round-medians min/max={min(meds):.1f}/{max(meds):.1f}")
    json.dump(receipt, open(sys.argv[1], 'w'), indent=1)
